\title{Symmetrized Monomial Identities of the Arrow Ideal\\ of an Acyclic Quiver}
\author{Aristotle}
\date{June 24, 2026}

\begin{document}
\maketitle

\begin{abstract}
Let $Q$ be a finite acyclic quiver whose longest directed path has length $n-1$, and let $\FF Q_{\ge 1}$ denote its \emph{arrow ideal}: the principal subalgebra of the path algebra spanned by all nonempty paths. We prove that two degree-$n$ multilinear polynomials---the \emph{symmetrized monomial} $S(x_1,\dots,x_n) = \sum_{\sigma \in S_n} x_{\sigma(1)} \cdots x_{\sigma(n)}$ and the \emph{standard polynomial} $S_n(x_1,\dots,x_n) = \sum_{\sigma \in S_n} \sgn(\sigma)\, x_{\sigma(1)} \cdots x_{\sigma(n)}$---are polynomial identities of $\FF Q_{\ge 1}$. The argument proceeds through a three-link chain: (i) acyclicity yields a strictly monotone potential $r$ bounding path length, $r(a) + \length(p) \le r(b)$; (ii) a topological order embeds $\FF Q_{\ge 1}$ in the strictly upper triangular $n\times n$ matrices $N_n$, nilpotent of index $n$; (iii) nilpotency of index $n$ makes every degree-$n$ multilinear polynomial vanish. The nilpotency step is governed by a quantitative \emph{shift filtration}: shift is additive under multiplication, and shift $n$ over $\FF^n$ forces the zero matrix. The \emph{unsigned} symmetrized monomial is already an identity here, in sharp contrast to full matrix algebras where (by Amitsur--Levitzki) only the \emph{signed} standard polynomial of degree $2n$ vanishes; in the nilpotent regime each monomial is individually zero, so signs are inert.
\end{abstract}

\section{Introduction}

\subsection{Motivation}
The theory of algebras with polynomial identity (PI-theory) studies associative algebras through the multilinear and polynomial laws they satisfy. The set of all such laws, the \emph{T-ideal} of identities, controls Gelfand--Kirillov dimension, codimension growth, and structural classification. The \emph{standard polynomial} is privileged by the Amitsur--Levitzki theorem: $M_k(\FF)$ satisfies $S_{2k}$ and no standard identity of lower degree.

This paper isolates the nilpotent shadow of that theory. The arrow ideal of a finite acyclic quiver is a structured, computable nilpotent algebra, modelled faithfully by strictly upper triangular matrices. We prove that the standard identity appears already in degree $n$ (the number of vertices), and that the unsigned symmetrized monomial of the same degree is also an identity. The contrast with $M_k$ illuminates two mechanisms: \emph{cancellation} (signs essential) versus \emph{individual annihilation} (signs inert).

\subsection{Summary of results}
The development rests on three pillars.
\begin{enumerate}
  \item \textbf{Geometric bound.} If $r : V \to \NN$ strictly increases along every arrow, then $r(a) + \length(p) \le r(b)$ for any path $p : a \to b$; if $r(v) < n$ for all $v$, every path has length $< n$.
  \item \textbf{Algebraic nilpotency.} Via the shift filtration, shift is additive under multiplication and shift $n$ vanishes; the product of any $n$ strictly upper triangular $n\times n$ matrices is zero.
  \item \textbf{Polynomial identities.} Every degree-$n$ multilinear monomial vanishes on $N_n$, so both $S$ and $S_n$ are identities of $N_n \cong \FF Q_{\ge 1}$.
\end{enumerate}

\section{Preliminaries and Definitions}

\subsection{Quivers, paths, and potentials}
A \emph{quiver} $Q$ is a directed multigraph with vertex set $V$ and arrows $a \to b$. A \emph{path} $p$ from $a$ to $b$ is a composable sequence of arrows with \emph{length} $\length(p)$ equal to the number of arrows (the empty path has length $0$). The quiver is \emph{acyclic} if there is no positive-length path from a vertex to itself.

\begin{definition}[Potential / topological order]
A \emph{potential} is a function $r : V \to \NN$ that is strictly monotone along arrows: $r(a) < r(b)$ for every arrow $a \to b$.
\end{definition}

A finite quiver admits a potential iff it is acyclic. We take the existence of a potential as the working hypothesis, keeping the path-length bound free of finiteness assumptions.

\subsection{Path algebra and arrow ideal}
Over a field $\FF$, the \emph{path algebra} $\FF Q$ has paths as a basis, with product given by concatenation when endpoints match and $0$ otherwise. The \emph{arrow ideal} is
\[
\FF Q_{\ge 1} = \operatorname{span}_{\FF}\{\, p : \length(p) \ge 1 \,\}.
\]
The product of $m$ basis elements is a path of length $\ge m$ (or zero); if all paths have length $< n$, any $n$-fold product is zero, i.e. $\FF Q_{\ge 1}$ is nilpotent of index $\le n$.

\subsection{The shift filtration}
Fix $n \in \NN$ and a semiring $R$; index $\Fin n = \{0,\dots,n-1\}$.

\begin{definition}[Shift]
$M \in M_n(R)$ \emph{has shift $k$} ($\Shift k\, M$) if $M_{ij} = 0$ whenever $j < i + k$.
\end{definition}

\begin{definition}[Strictly upper triangular]
$M$ is \emph{strictly upper triangular} ($\StrictUpper M$) if $\Shift 1\, M$; equivalently $M_{ij} = 0$ whenever $j \le i$.
\end{definition}

The strictly upper triangular matrices $N_n := \{M : \Shift 1\, M\}$ form the algebraic model of $\FF Q_{\ge 1}$ after relabelling vertices as $0,\dots,n-1$.

\subsection{Multilinear polynomials}
\begin{definition}[Symmetrized monomial]
For $a_1,\dots,a_n$ in an associative ring $A$,
$S(a) = \sum_{\sigma \in S_n} a_{\sigma(1)} \cdots a_{\sigma(n)}.$
\end{definition}
\begin{definition}[Standard polynomial]
$S_n(a) = \sum_{\sigma \in S_n} \sgn(\sigma)\, a_{\sigma(1)} \cdots a_{\sigma(n)}.$
\end{definition}
Both are multilinear of degree $n$. A polynomial $f$ is an \emph{identity} of $A$ if it vanishes for all substitutions in $A$.

\section{The Geometric Bound}

\begin{theorem}[Potential bound, \texttt{r\_add\_length\_le}]
Let $r$ be a potential. Then for every path $p : a \to b$, $r(a) + \length(p) \le r(b)$.
\end{theorem}
\begin{proof}[Proof sketch]
Induct on $p$. For the empty path, $\length = 0$ and $r(a) \le r(a)$. Writing $p = q$ followed by an arrow $b' \to b$: by induction $r(a) + \length(q) \le r(b')$, and $r(b') < r(b)$, i.e. $r(b')+1 \le r(b)$. Since $\length(p) = \length(q)+1$,
$r(a) + \length(p) \le r(b') + 1 \le r(b)$.
\end{proof}

The bound is sharp on the linear quiver $A_n$ with $r = \mathrm{id}$: the full path attains $0 + (n-1) = n-1$.

\begin{theorem}[Length bound, \texttt{length\_lt\_of\_bounded}]
If $r$ is a potential with $r(v) < n$ for all $v$, then every path $p$ satisfies $\length(p) < n$.
\end{theorem}
\begin{proof}[Proof sketch]
$r(a) + \length(p) \le r(b) < n$ and $r(a) \ge 0$ give $\length(p) < n$.
\end{proof}

\section{Nilpotency via the Shift Filtration}

\begin{lemma}[\texttt{Shift.one}]
The identity matrix $I \in M_n(R)$ has shift $0$.
\end{lemma}
\begin{proof}[Proof sketch]
For $i \ne j$, $I_{ij} = 0$; for $i = j$, the constraint $j < i$ is false. So $I_{ij}=0$ whenever $j < i+0$.
\end{proof}

\begin{theorem}[Shift additivity, \texttt{Shift.mul}]
If $\Shift k\, M$ and $\Shift l\, N$, then $\Shift(k+l)\,(MN)$.
\end{theorem}
\begin{proof}[Proof sketch]
$(MN)_{ij} = \sum_x M_{ix} N_{xj}$. Assume $j < i+k+l$. If $x < i+k$ then $M_{ix}=0$; otherwise $x \ge i+k$ gives $j < x+l$ so $N_{xj}=0$. Every summand vanishes.
\end{proof}

\begin{theorem}[Top shift vanishes, \texttt{Shift.eq\_zero\_of\_top}]
If $\Shift n\, M$ for $M \in M_n(R)$, then $M = 0$.
\end{theorem}
\begin{proof}[Proof sketch]
For all $i,j \in \Fin n$, $j < n \le i + n$, so $M_{ij}=0$ everywhere.
\end{proof}

\begin{theorem}[List product shift, \texttt{listProd\_shift}]
If $\ell$ is a list of matrices each satisfying $\StrictUpper$, then $\prod \ell$ has shift $|\ell|$.
\end{theorem}
\begin{proof}[Proof sketch]
Induct on $\ell$. Empty: $I$, shift $0$. Step: shift $1 + |\ell|$ by additivity.
\end{proof}

\begin{theorem}[Nilpotency, \texttt{prod\_ofFn\_strictUpper\_eq\_zero}]
If $a : \Fin n \to M_n(R)$ with $\StrictUpper(a_i)$ for all $i$, then $\prod_{i=0}^{n-1} a_i = 0$.
\end{theorem}
\begin{proof}[Proof sketch]
The list of the $n$ strictly upper triangular $a_i$ has product of shift $n$; a shift-$n$ matrix over $\Fin n$ is zero.
\end{proof}

The matrix monoid is noncommutative, so products are ordered \texttt{List.prod}; the conclusion (product $=0$) is independent of order.

\section{Polynomial Identities of the Arrow Ideal}

\begin{theorem}[Symmetrized monomial identity, \texttt{PI.symMono\_strictUpper\_eq\_zero}]
For every $a : \Fin n \to N_n$, $S(a) = \sum_{\sigma} a_{\sigma(1)} \cdots a_{\sigma(n)} = 0$.
\end{theorem}
\begin{proof}[Proof sketch]
Each term is a degree-$n$ product of strictly upper triangular matrices, hence $0$; the sum of $n!$ zeros is $0$.
\end{proof}

\begin{theorem}[Standard identity, \texttt{PI.stdPoly\_strictUpper\_eq\_zero}]
For every $a : \Fin n \to N_n$, $S_n(a) = \sum_{\sigma} \sgn(\sigma)\, a_{\sigma(1)} \cdots a_{\sigma(n)} = 0$.
\end{theorem}
\begin{proof}[Proof sketch]
Each signed term is a scalar multiple of a degree-$n$ product of strictly upper triangular matrices, hence $0$. Signs are irrelevant since each monomial vanishes individually.
\end{proof}

\begin{proposition}[Nilpotency $\Rightarrow$ multilinear identities]
Let $A$ be an associative ring and $J \subseteq A$ closed under multiplication with every $n$-fold product of elements of $J$ equal to $0$. Then every degree-$n$ multilinear polynomial (in particular $S$ and $S_n$) is an identity of $J$.
\end{proposition}
\begin{proof}[Proof sketch]
A multilinear degree-$n$ polynomial is a linear combination of $n$-fold product monomials, each $0$ by hypothesis.
\end{proof}

\section{The Signed/Unsigned Dichotomy}
The Amitsur--Levitzki theorem asserts $M_k(\FF)$ satisfies $S_{2k}$ and no standard identity of degree $< 2k$, by delicate sign cancellation; the unsigned symmetrized monomial does \emph{not} vanish on $M_k$. On $N_n \subset M_n(\FF)$ the standard identity appears at degree $n$ and the unsigned symmetrized monomial is also an identity, because each monomial is individually zero. This motivates Conjecture~\ref{conj:dichotomy}.

\section{Algorithms}
\paragraph{Topological potential and longest path.} Kahn's algorithm yields a topological order; a DP pass computes $\mathrm{lp}(v) = \max(0, \max_{u\to v}\mathrm{lp}(u)+1)$ in $O(|V|+|E|)$. By Theorem~4.2 the longest path length is $\le |V|-1$.
\paragraph{Shift and nilpotency check.} For each $M$, report the largest $k$ with $\Shift k\, M$; shift additivity predicts $\Shift(\sum k_i)$ for products, and $t=n$ strictly upper triangular factors give $0$. Cost $O(t\,n^3)$.
\paragraph{Multilinear identity evaluation.} Enumerate all $n!$ permutations and accumulate (signed) products; the result is the zero matrix for every strictly upper triangular input. Cost $O(n!\,n\cdot n^3)$.

\section{Applications}
\begin{itemize}
  \item Representation theory: the arrow-ideal nilpotency index governs the radical filtration of acyclic path algebras.
  \item PI-theory of triangular algebras: explicit degree-$n$ multilinear identities for $N_n$ and $UT_n$.
  \item Verified static analysis: acyclicity of dependency graphs guarantees bounded composition depth via a checkable matrix-degree invariant.
\end{itemize}

\section{Discussion and Future Directions}
This cycle proves the \emph{containment} half: $S$ and $S_n$ are identities of $\FF Q_{\ge 1}$. The \emph{generation} half remains open.

\begin{conjecture}[Degree sharpness]
$N_n$ satisfies no multilinear identity of degree $< n$. Witness: $E_{12}E_{23}\cdots E_{n-1,n} = E_{1,n} \ne 0$, a nonzero product of $n-1$ strictly upper triangular matrices.
\end{conjecture}

\begin{conjecture}[T-ideal generation]
$\Id(N_n)$ is generated as a T-ideal by the single standard polynomial $S_n$.
\end{conjecture}

\begin{conjecture}[Unsigned/signed dichotomy]\label{conj:dichotomy}
An associative algebra satisfies the degree-$n$ unsigned symmetrized identity iff its augmentation ideal is nilpotent of index $\le n$; on $M_k$ only the signed standard polynomial (degree $2k$) holds.
\end{conjecture}

\begin{conjecture}[Quiver-shape refinement]
For a general acyclic $Q$, the minimal identity degree equals $1 + (\text{longest directed path length})$, independent of the number of vertices.
\end{conjecture}

\section{Conclusion}
From the combinatorial fact that an acyclic quiver on $n$ vertices admits no path of length $n$, we derived---via a quantitative shift filtration---the nilpotency of the arrow ideal and two degree-$n$ polynomial identities of $\FF Q_{\ge 1}$. The validity of the unsigned identity, impossible on full matrix algebras, marks the nilpotent regime as governed by individual annihilation rather than signed cancellation.

