function TOPOLOGICAL_POTENTIAL(n, edges):
    succ <- adjacency lists; indeg <- in-degree array
    queue <- all v with indeg[v] = 0
    r[v] <- 0 for all v
    visited <- 0
    while queue not empty:
        u <- queue.pop(); visited <- visited + 1
        for w in succ[u]:
            r[w] <- max(r[w], r[u] + 1)
            indeg[w] <- indeg[w] - 1
            if indeg[w] = 0: queue.push(w)
    if visited != n: error 'not acyclic'
    return r

